#[path="../src/remaining_types/state_machine_v1.rs"]mod state_machine_v1;
use state_machine_v1::*;
#[test]fn native_transitions_are_deterministic_and_return_intents_only(){let first=transition("pending","confirm",true);let again=transition("pending","confirm",true);assert_eq!(first,again);assert_eq!(first.next_state,Some("settled"));assert_eq!(first.effect_intents,vec!["persist-settlement","append-settlement-created"]);assert_eq!(transition("pending","reject",true).next_state,Some("failed"));assert!(!transition("settled","confirm",true).accepted);assert_eq!(decode_effect_intent(&["effect_intent_id","payload","execute"]),Err("RMT_S1_CLOSED_DECODE_UNKNOWN_MEMBER"));}
#[test]fn kills_all_ten_semantic_controls_as_singletons(){let mut cases:Vec<(&str,StateMachineObservation)>=Vec::new();let mut v=baseline();v.illegal_transition_observed=true;cases.push(("RMT_SM_ILLEGAL_TRANSITION",v));let mut v=baseline();v.observed_initial_state="failed";cases.push(("RMT_SM_INITIAL_STATE_DRIFT",v));let mut v=baseline();v.observed_terminal_states=vec!["failed"];cases.push(("RMT_SM_TERMINAL_STATE_DRIFT",v));let mut v=baseline();v.guard_bypass_observed=true;cases.push(("RMT_SM_GUARD_BYPASS",v));let mut v=baseline();v.nondeterministic_outcome_observed=true;cases.push(("RMT_SM_NONDETERMINISTIC_TRANSITION",v));let mut v=baseline();v.effects_performed_inline.push("write");cases.push(("RMT_SM_EXECUTES_EFFECT",v));let mut v=baseline();v.observed_cycle_policy="forbidden";cases.push(("RMT_SM_CYCLE_POLICY_MISMATCH",v));let mut v=baseline();v.invalid_transition_accepted=true;cases.push(("RMT_SM_INVALID_TRANSITION_SUCCESS",v));let mut v=baseline();v.hidden_mutation_observed=true;cases.push(("RMT_SM_HIDDEN_MUTATION",v));let mut v=baseline();v.stable_transition_ids=false;cases.push(("RMT_SM_UNSTABLE_TRANSITION_IDENTITY",v));assert_eq!(cases.len(),10);for(expected,observed)in cases{assert_eq!(evaluate(&observed),vec![expected],"{expected}");}}
